mapper.select:
SELECT * FROM watch_history
WHERE user_id = #{userId}
ORDER BY watch_time DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM watch_history
WHERE user_id = #{userId}
  AND video_id NOT IN (
    SELECT video_id FROM (
        SELECT video_id FROM watch_history
        WHERE user_id = #{userId}
        ORDER BY watch_time DESC
        LIMIT #{keepCount}
    ) t
  )
